FILE = "idris-elba-kenya-creative-economy.html"
TITLE = "Kenya signs a creative economy deal with Idris Elba"
TAG = "The Wrap"
H1 = "Kenya signs a creative economy deal with Idris Elba"
DEK = "The government and the actor's Akuna Group have agreed to work together on funding, AI training and global market access for young Kenyan creatives."
META = "The Wrap · Local · 6 Nov 2026 · 3 min read"
LEAD = ("img/wr-idris-elba.jpg", "Sir Idris Elba at the signing with Kenya on the sidelines of CHOGM 2026 in Antigua and Barbuda")

BODY = [
("p", "Kenya has signed a partnership with Sir Idris Elba aimed at young people working in the creative industries. The agreement, a Statement of Intent, was signed on Tuesday 3 November 2026 on the sidelines of the Commonwealth Heads of Government Meeting (CHOGM) in Antigua and Barbuda."),
("p", "Foreign Affairs Principal Secretary Korir Sing’oei signed for Kenya. Elba signed as chairman of the Akuna Group, the creative, entertainment and media company he founded."),
("h2", "The deal", "What it ", "covers"),
("p", "The statement sets up a framework for the two sides to cooperate on the creative economy, artificial intelligence, digital innovation, skills training and access to international markets. In practice, the focus is on helping young creatives find financing for their work, build their skills and sell what they make beyond Kenya."),
("p", "It is meant to support the government’s Talanta Hela programme, and it brings Kenya into the Commonwealth Creative Economy Partnership alongside Ghana, Sierra Leone and Barbados. Sing’oei said the ambition is to connect Kenya’s “extraordinary creative talent to technology, investment and opportunities.”"),
("p", "No funding figures have been made public."),
("h2", "The background", "How it ", "started"),
("p", "The deal follows a virtual meeting between Elba and Sing’oei in September about the problems young African artists and creative entrepreneurs face. Elba pointed to professional networks, access to international markets and reliable payment systems as the things they need most."),
("p", "The Akuna Group already runs an AI filmmaking training and mentorship programme for African filmmakers with Google and the online school Curious Refuge, which Elba announced in October. Selected projects receive production funding, and the filmmakers keep ownership of their work."),
("h2", "What’s next", "Coming to ", "Kenya"),
("p", "On behalf of President William Ruto, Sing’oei invited Elba to visit Kenya for the upcoming Internet Governance Forum, where the full programme is expected to be unveiled."),
]

